import React, { useState, useEffect, useCallback } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { format, startOfMonth, endOfMonth, isWithinInterval, subMonths, parseISO } from 'date-fns';

const DEFAULT_BUDGETS = {
  Food: 600, Transport: 200, Entertainment: 150, Shopping: 300,
  Health: 100, Utilities: 200, Rent: 1500, Savings: 500, Other: 200,
};

const SEED_DATA = () => {
  const txns = [];
  const now = new Date();
  const categories = ['Food','Transport','Entertainment','Shopping','Health','Utilities','Rent'];
  const expDescs = {
    Food:['Grocery run','Restaurant dinner','Coffee & snacks','Meal prep'],
    Transport:['Gas fill-up','Uber ride','Monthly transit pass','Parking'],
    Entertainment:['Netflix subscription','Movie tickets','Concert','Gaming'],
    Shopping:['Clothes haul','Amazon order','Home decor','Tech gadget'],
    Health:['Gym membership','Pharmacy','Doctor visit','Supplements'],
    Utilities:['Electric bill','Internet bill','Water bill','Phone plan'],
    Rent:['Monthly rent','Storage unit'],
  };
  for (let m = 5; m >= 0; m--) {
    const month = subMonths(now, m);
    txns.push({
      id: uuidv4(), type: 'income', amount: 3200 + Math.random() * 800,
      category: 'Salary', description: 'Monthly salary',
      date: format(new Date(month.getFullYear(), month.getMonth(), 1), 'yyyy-MM-dd'),
    });
    if (Math.random() > 0.5) {
      txns.push({
        id: uuidv4(), type: 'income', amount: 200 + Math.random() * 600,
        category: 'Freelance', description: 'Freelance project',
        date: format(new Date(month.getFullYear(), month.getMonth(), 15), 'yyyy-MM-dd'),
      });
    }
    categories.forEach(cat => {
      const count = cat === 'Rent' ? 1 : Math.floor(Math.random() * 4) + 1;
      for (let i = 0; i < count; i++) {
        const descs = expDescs[cat] || ['Miscellaneous'];
        txns.push({
          id: uuidv4(), type: 'expense',
          amount: cat === 'Rent' ? 1450 : 20 + Math.random() * (DEFAULT_BUDGETS[cat] / count),
          category: cat,
          description: descs[Math.floor(Math.random() * descs.length)],
          date: format(new Date(month.getFullYear(), month.getMonth(), Math.floor(Math.random() * 28) + 1), 'yyyy-MM-dd'),
        });
      }
    });
  }
  return txns;
};

function storageKey(userId, type) {
  return `finova_${userId}_${type}`;
}

function load(key) {
  try { const r = localStorage.getItem(key); return r ? JSON.parse(r) : null; } catch { return null; }
}
function save(key, val) {
  try { localStorage.setItem(key, JSON.stringify(val)); } catch {}
}

export function useFinance(userId) {
  const txnKey = storageKey(userId || 'guest', 'transactions');
  const budgetKey = storageKey(userId || 'guest', 'budgets');

  const [transactions, setTransactions] = useState(() => load(txnKey) || SEED_DATA());
  const [budgets, setBudgets] = useState(() => load(budgetKey) || DEFAULT_BUDGETS);
  const [selectedMonth, setSelectedMonth] = useState(() => format(new Date(), 'yyyy-MM'));


  useEffect(() => {
    setTransactions(load(txnKey) || SEED_DATA());
    setBudgets(load(budgetKey) || DEFAULT_BUDGETS);
  }, [txnKey, budgetKey]); // txnKey/budgetKey change when userId changes

  useEffect(() => { if (userId) save(txnKey, transactions); }, [transactions, txnKey, userId]);
  useEffect(() => { if (userId) save(budgetKey, budgets); }, [budgets, budgetKey, userId]);

  const monthTransactions = useCallback((monthStr) => {
    const [y, m] = monthStr.split('-').map(Number);
    const start = startOfMonth(new Date(y, m - 1));
    const end = endOfMonth(new Date(y, m - 1));
    return transactions.filter(t => {
      const d = parseISO(t.date);
      return isWithinInterval(d, { start, end });
    });
  }, [transactions]);

  const currentTxns = monthTransactions(selectedMonth);
  const totalIncome = currentTxns.filter(t => t.type === 'income').reduce((s, t) => s + t.amount, 0);
  const totalExpenses = currentTxns.filter(t => t.type === 'expense').reduce((s, t) => s + t.amount, 0);
  const netSavings = totalIncome - totalExpenses;
  const savingsRate = totalIncome > 0 ? (netSavings / totalIncome) * 100 : 0;

  const categoryBreakdown = {};
  currentTxns.filter(t => t.type === 'expense').forEach(t => {
    categoryBreakdown[t.category] = (categoryBreakdown[t.category] || 0) + t.amount;
  });

  const budgetAlerts = Object.entries(budgets).map(([cat, limit]) => {
    const spent = categoryBreakdown[cat] || 0;
    const pct = limit > 0 ? (spent / limit) * 100 : 0;
    return { category: cat, spent, limit, pct, over: pct >= 100, warning: pct >= 80 && pct < 100 };
  }).filter(a => a.pct > 0);

  const monthlyTrend = Array.from({ length: 6 }, (_, i) => {
    const d = subMonths(new Date(), 5 - i);
    const key = format(d, 'yyyy-MM');
    const txns = monthTransactions(key);
    const income = txns.filter(t => t.type === 'income').reduce((s, t) => s + t.amount, 0);
    const expenses = txns.filter(t => t.type === 'expense').reduce((s, t) => s + t.amount, 0);
    return { month: format(d, 'MMM'), income, expenses, savings: income - expenses };
  });

  const addTransaction = (txn) => setTransactions(prev => [{ ...txn, id: uuidv4() }, ...prev]);
  const deleteTransaction = (id) => setTransactions(prev => prev.filter(t => t.id !== id));
  const updateBudget = (cat, val) => setBudgets(prev => ({ ...prev, [cat]: Number(val) }));

  return {
    transactions, selectedMonth, setSelectedMonth,
    currentTxns, totalIncome, totalExpenses, netSavings, savingsRate,
    categoryBreakdown, budgets, budgetAlerts, monthlyTrend,
    addTransaction, deleteTransaction, updateBudget,
  };
}
